async function api(path,options={}){
  const response=await fetch(path,{...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}});
  let result;try{result=await response.json();}catch{throw new Error('本地服务返回了无法读取的响应，请刷新后重试。');}
  if(!response.ok)throw new Error(result.error?.message||`请求失败（${response.status}）`);
  return result;
}
