function collectParameters(withReferences=true){const raw=$('prompt-mode').value==='raw';return{provider:$('provider').value,model:$('model').value,n:Number($('image-count').value),prompt_mode:$('prompt-mode').value,negative_prompt:raw?'':$('negative-prompt').value.trim(),size:raw?'auto':$('image-size').value.trim()||'auto',aspect_ratio:raw?null:$('aspect-ratio').value||null,full_size:$('full-size').value==='true',response_format:$('response-format').value,reference_images:withReferences?references.map(item=>item.id):[]};}
