  $('composer-status').textContent=usable(id)?(submitting?'正在提交…':id==='pollinations'?'使用公共 Sana（可能限流）':id==='puter'?'使用 Puter User-Pays 账户':'使用网页账号额度'):online?'连接平台后即可开始':'等待本地服务恢复';
