function populateModels(id,data){models[id]=data;const item=provider(id),selected=selectedModels[id] || (id==='gemini'?'gemini-pro':item?.default_model||'default');if($('provider').value!==id)return;$('model').replaceChildren();for(const raw of data){const model=typeof raw==='string'?{id:raw,display_name:raw}:raw;if(model.available===false && id==='gemini')continue;if(!model.id)continue;$('model').add(new Option(model.display_name||model.id,model.id));}if(![...$('model').options].some(option=>option.value==='default'))$('model').add(new Option('平台默认模型','default'));if(!nativeModelsLoaded&&![...$('model').options].some(option=>option.value===selected)&&id==='gemini')$('model').add(new Option(selected,selected));$('model').value=[...$('model').options].some(option=>option.value===selected)?selected:'default';selectedModels[id]=$('model').value;$('model').disabled=!['native','public'].includes(item?.mode) && id!=='gemini';updateControls();}
