$('choose-references').addEventListener('click',()=>$('reference-files').click());
$('reference-files').addEventListener('change',async()=>{const files=[...$('reference-files').files];$('reference-files').value='';if(!files.length)return;$('reference-error').hidden=true;try{const maxReferences=limitValue('reference_images',10),maxBytes=limitValue('reference_image_bytes',100*1024*1024),maxTotalBytes=limitValue('reference_total_bytes',100*1024*1024);if(files.length+references.length>maxReferences)throw new Error(`一次最多使用 ${maxReferences} 个参考文件。`);if(files.some(file=>file.size>maxBytes))throw new Error(`每张参考图最大 ${Math.round(maxBytes/(1024*1024))} MB。`);const currentBytes=references.reduce((sum,item)=>sum+(Number(item.bytes)||0),0),incomingBytes=files.reduce((sum,file)=>sum+file.size,0);if(currentBytes+incomingBytes>maxTotalBytes)throw new Error(`本次参考图总大小不能超过 ${Math.round(maxTotalBytes/(1024*1024))} MB。`);uploading=true;renderReferences();const form=new FormData();for(const file of files)form.append('files',file);references.push(...(await api('/api/references',{method:'POST',body:form})).data);toast('参考图已保存到本机');}catch(error){$('reference-error').textContent=error.message;$('reference-error').hidden=false;}finally{uploading=false;renderReferences();}});
$('generate-form').addEventListener('submit',async event=>{event.preventDefault();if(submitting||uploading)return;submitting=true;updateControls();$('form-error').hidden=true;try{const common=collectParameters();const lines=promptLines(),maxBatch=limitValue('batch_prompts',20);if(batchMode && (!lines.length||lines.length>maxBatch))throw new Error(`每批需要 1–${maxBatch} 条提示词。`);await api(batchMode?'/api/batches':'/api/jobs',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(batchMode?{items:lines.map((prompt,index)=>({...common,prompt,custom_id:`item-${index+1}`}))}:{...common,prompt:currentPrompt()})});toast(batchMode?`已提交 ${lines.length} 条提示词，已加入生成队列`:'已加入生成队列');await refresh();}catch(error){$('form-error').textContent=error.message;$('form-error').hidden=false;}finally{submitting=false;updateControls();}});

// Copyable, provider-aware request examples; no real keys are embedded.
const clientConfig=parameters=>({base_url:location.origin+'/v1',api_key:'${GEMINI_WEB2API_KEY}',parameters:{...parameters,reference_images:[]}});
const shellQuote=value=>"'"+value.replaceAll("'","'\\''")+"'";
function curl(path,payload,key){return [`curl ${location.origin}/v1/${path} \\`,`  -H 'Authorization: Bearer YOUR_API_KEY' \\`,`  -H 'Content-Type: application/json' \\`,`  -H 'Idempotency-Key: ${key}' \\`,`  -d ${shellQuote(JSON.stringify(payload,null,2))}`].join('\n');}
function videoParameters(withReferences=true){return{provider:$('video-provider').value,model:$('video-model').value,prompt:$('video-prompt').value.trim(),duration:Number($('video-duration').value),resolution:$('video-resolution').value,aspect_ratio:$('video-aspect-ratio').value,audio:$('video-audio').checked,reference_images:withReferences?videoReferences.map(item=>item.id):[]};}
function codeExample(){const params=collectParameters(false),prompt=currentPrompt()||'生成一只白色陶瓷杯的产品摄影图';if(codeMode==='config')return JSON.stringify(clientConfig(params),null,2);if(codeMode==='chat')return curl('chat/completions',{provider:$('chat-provider').value,model:'default',messages:[{role:'user',content:$('chat-prompt').value||'请给我三个产品摄影创意。'}],stream:false},'my-chat-001');if(codeMode==='video'){const video=videoParameters(false);video.prompt=video.prompt||'人物自然走向镜头，镜头缓慢推进，保持人物外观稳定。';return curl('videos/generations',video,'my-video-001');}if(codeMode==='batch'){const lines=batchMode&&promptLines().length?promptLines():[prompt,'生成一幅湖边水彩风景'];return curl('batches',{items:lines.map((value,index)=>({...params,prompt:value,custom_id:`item-${index+1}`}))},'my-batch-001');}if(codeMode==='edit')return [`curl ${location.origin}/v1/references \\`,`  -H 'Authorization: Bearer YOUR_API_KEY' \\`,"  -F 'files=@/absolute/path/reference.png'",'','# 将返回的完整 ref_… ID 填入 reference_images',curl('images/generations',{...params,prompt,reference_images:['ref_替换为项目上传返回的完整ID']},'my-edit-001')].join('\n');return curl('images/generations',{...params,prompt},'my-image-001');}
function renderCode(){$('curl-example').textContent=codeExample();$('code-note').textContent=codeMode==='chat'?'对话示例使用文字对话页所选的平台。messages 会作为文本上下文发送到新网页会话；不支持 stream:true。':codeMode==='video'?'视频示例使用账号页保存的平台凭据，调用 Key 仍然是本地网关项目 Key。参考图需要先上传并填写返回的 ref_ ID。':'参数与图片工作台同步。请替换为项目调用 Key；参考图需要用同一个项目 Key 单独上传。';}
function selectCode(mode){codeMode=mode;for(const value of ['single','edit','batch','video','chat','config']){const button=$(value+'-code');if(button)button.classList.toggle('selected',value===mode);}renderCode();}
for(const mode of ['single','edit','batch','video','chat','config'])$(mode+'-code').addEventListener('click',()=>selectCode(mode));
$('copy-curl').addEventListener('click',()=>copy(codeExample()));$('copy-endpoint').addEventListener('click',()=>copy(location.origin+'/v1'));
function syncLimitControls(){
  const promptLimit=limitValue('prompt_characters',16000),negativeLimit=limitValue('negative_prompt_characters',16000),batchLimit=limitValue('batch_prompts',20),outputLimit=limitValue('output_images',4),chatMessageLimit=limitValue('chat_message_characters',32000);
  const signature=JSON.stringify([promptLimit,negativeLimit,batchLimit,outputLimit,chatMessageLimit,limitValue('chat_total_characters',64000),limitValue('chat_messages',80),limitValue('pending_jobs',20),limitValue('reference_images',10),limitValue('reference_image_bytes',100*1024*1024),limitValue('reference_total_bytes',100*1024*1024),limitValue('reference_image_pixels',25000000)]);if(signature===appliedLimits)return;appliedLimits=signature;
  $('prompt').maxLength=promptLimit;$('negative-prompt').maxLength=negativeLimit;$('batch-prompts').maxLength=promptLimit*batchLimit+batchLimit;$('chat-system').maxLength=chatMessageLimit;$('chat-prompt').maxLength=chatMessageLimit;
  const count=$('image-count'),selected=Number(count.value)||1;if(count.options.length!==outputLimit){count.replaceChildren(...Array.from({length:outputLimit},(_,index)=>new Option(`${index+1} 张`,String(index+1))));count.value=String(Math.min(selected,outputLimit));}
  countPrompts();countChatCharacters();renderReferences();
}
async function validatedConfig(){const response=await api('/api/requests/preview',{method:'POST',body:JSON.stringify({...collectParameters(false),prompt:'配置验证'})});const{prompt,...parameters}=response.parameters;return clientConfig(parameters);}
