function renderKeys(data){keys=data;$('key-count').textContent=`${keys.filter(key=>key.enabled).length} 个有效 Key`;const serial=JSON.stringify(data);if(serial===lastKeys)return;lastKeys=serial;$('keys-list').replaceChildren();if(!keys.length){$('keys-list').append(el('p','no-keys','还没有调用 Key。为第一个项目创建一把钥匙。'));return;}for(const key of keys){const row=el('div','key-row'),label=el('div','key-label');label.append(el('strong','',key.name),el('span','',`${key.prefix} · ${key.last_used_at?'最近调用 '+timeLabel(key.last_used_at):'尚未调用'}`));row.append(el('span','key-icon','⚿'),label,el('span','key-state',key.enabled?'有效':'已停用'));if(key.enabled){const button=el('button','text-button','停用');button.addEventListener('click',async()=>{if(!button.dataset.confirm){button.dataset.confirm='true';button.textContent='确认停用';return;}button.disabled=true;try{await api('/api/keys/'+key.id+'/revoke',{method:'POST'});await refresh();toast('调用 Key 已停用');}catch(error){toast(error.message);button.disabled=false;}});row.append(button);}$('keys-list').append(row);}}
$('chat-form').addEventListener('submit',async event=>{event.preventDefault();$('chat-send').dataset.busy='true';$('chat-send').disabled=true;$('chat-error').hidden=true;try{const messages=[];if($('chat-system').value.trim())messages.push({role:'system',content:$('chat-system').value});messages.push({role:'user',content:$('chat-prompt').value});await api('/api/chat/jobs',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({provider:$('chat-provider').value,model:'default',messages,stream:false})});toast('对话已加入队列');await refresh();}catch(error){$('chat-error').textContent=error.message;$('chat-error').hidden=false;}finally{$('chat-send').dataset.busy='false';updateControls();}});
