function renderChat(){const job=jobs.find(item=>item.kind==='chat');if(!job)return;const pending=['queued','running','waiting'].includes(job.status);$('chat-answer').classList.toggle('answer-empty',!job.text);$('chat-answer').textContent=job.text||job.error?.message||(pending?'正在等待网页回复…':'这次对话没有返回文字');$('chat-meta').textContent=`${providerLabel(job)} · ${timeLabel(job.created_at)} · ${statusLabels[job.status]}`;$('copy-chat').disabled=!job.text;$('copy-chat').dataset.jobId=job.id;}
