async function refresh(){if(refreshPromise)return refreshPromise;refreshPromise=(async()=>{try{const[state,records,platforms,keyList,accountList,videoList,webImageList]=await Promise.all([api('/health'),api('/api/jobs'),api('/api/providers'),api('/api/keys'),api('/api/accounts'),api('/api/video-providers'),api('/api/web-image-providers')]);health=state;renderAccounts(accountList);renderProviders(platforms);renderVideoProviders(videoList,webImageList);updateHealth(state);renderKeys(keyList.data);const serial=JSON.stringify(records.data);jobs=records.data.filter(job=>providerOf(job)!=='chatgpt');$('nav-job-count').textContent=jobs.length;$('stat-images').textContent=jobs.reduce((total,job)=>total+job.images.length,0);if(serial!==lastJobs){lastJobs=serial;renderHistory();renderPreview();renderVideo();renderChat();}}catch{online=false;$('connection-status').className='connection-status offline';$('connection-status').textContent='本地服务未响应';updateControls();updateVideoControls();}finally{refreshPromise=null;}})();return refreshPromise;}
