          if(item.id==='seaart-web')creditsResult.textContent=`免费 coins ${credits.free_coins??'—'} · 临时免费 ${credits.temp_free_coins??'—'} · 试用 ${credits.try_out_limit??'—'} · 可用免费 ${credits.free_available??'—'}`;
