    const label=isBing?'Bing _U Cookie Value':isRecraft?'Recraft 网页 Bearer Token':isLeonardo?'Leonardo 网页 Bearer Token':isSeaArt?'SeaArt Token + model_no JSON':isWhisk?'Google Flow / Whisk 兼容 Cookie':'Google Labs Cookie Header 或 Bearer Token';
    const hint=isBing?'填写 bing.com Cookie 中 _U 的 Value':isRecraft?'从已登录 Recraft 网页的请求 Authorization 中复制 Bearer Token；只保存在本机':isLeonardo?'从已登录 Leonardo 网页请求 Authorization 中复制 Bearer Token；只保存在本机':isSeaArt?'JSON：{"token":"网页 Token","model_no":"网页模型 ID","model_ver_no":"可选版本 ID","device_id":"可选固定设备 ID"}（不生成设备指纹）':isWhisk?'Whisk 已迁移到 Google Flow；旧 Cookie 仅用于兼容实测，当前不保证纯 HTTP 可用':'建议从 labs.google/fx/tools/image-fx 的请求中复制 Cookie Header；也可填短期 Bearer Token';
    const form=el('form','video-key-form'),input=el('input'),button=el('button','button secondary small',isSeaArt?'保存 SeaArt JSON':'保存网页凭据'),clear=el('button','button secondary small','清除'),message=el('p','settings-message');
    input.type='password';input.autocomplete='new-password';input.placeholder=item.configured?`已保存，填写新的${isSeaArt?' SeaArt JSON':isBing?' _U Cookie':isRecraft||isLeonardo?' Bearer Token':'凭据'} 可覆盖`:hint;input.setAttribute('aria-label',`${item.name} ${label}`);input.maxLength=65536;button.type='submit';clear.type='button';clear.hidden=!item.configured;message.hidden=true;form.append(input,button,clear,message);
