$('video-form').addEventListener('submit',async event=>{event.preventDefault();if(videoSubmitting||videoUploading)return;videoSubmitting=true;$('video-form-error').hidden=true;updateVideoControls();try{const payload=videoParameters();if(!payload.prompt)throw new Error('请先填写视频提示词。');await api('/api/video/jobs',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(payload)});toast('视频任务已加入队列');await refresh();}catch(error){$('video-form-error').textContent=error.message;$('video-form-error').hidden=false;}finally{videoSubmitting=false;updateVideoControls();}});
