  if(latest){const relative=latest.videos[latest.videos.length-1],player=el('video');player.controls=true;player.playsInline=true;player.preload='metadata';player.src=videoURL(relative);player.addEventListener('click',()=>openVideo(latest,latest.videos.length-1));$('video-preview-area').replaceChildren(player);$('video-preview-status').textContent=active?'新任务进行中':'已保存到本机';const download=el('a','','下载视频 ↓');download.href=videoURL(relative);download.download=relative.split('/').pop();$('video-preview-caption').replaceChildren(el('span','',`${providerName(providerOf(latest))} · 点击播放器查看详情`),download);videoJob=latest;}
  else if(active){const wrap=el('div','busy-state');wrap.append(el('span','spinner'),el('span','',active.status==='running'?`${providerName(providerOf(active))} 正在生成`:'视频任务排队中'),el('p','',active.request.reference_images?.length?'参考图已随任务提交。':'可以稍后回来查看视频。'));$('video-preview-area').replaceChildren(wrap);$('video-preview-status').textContent=statusLabels[active.status]||active.status;$('video-preview-caption').textContent='视频生成完成后会自动保存到本机。';}
  else{const empty=el('div','empty-preview');empty.append(el('span','empty-art','▶'),el('strong','','上传一张参考图，开始试片'),el('p','','可选首帧、首尾帧或主体参考图。'));$('video-preview-area').replaceChildren(empty);$('video-preview-status').textContent='等待灵感';$('video-preview-caption').textContent='视频会自动保存到本机。';}
